"""Templates for sentinelx init."""

SITE_TEMPLATE = """# SentinelX Site Guard Configuration
# Generated by: sentinx init
# Edit this file to configure your target sites.

version: "1.0"

# List of targets to protect
targets:
  # Example lab target (localhost/127.0.0.1/*.lab.test only)
  - id: "vibe_notes_node"
    name: "Vibe Notes Node Lab"
    base_url: "http://127.0.0.1:18081"
    lab: true
    # scan_profile: "default"  # optional, references a scan profile
    # fix_policy: "auto"  # or "manual", "auto"

# Example non-lab target (requires ownership verification)
# - id: "my_production_site"
#   name: "Production Site"
#   base_url: "https://example.com"
#   lab: false
#   # Ownership token will be generated on `sentinelx site add`
#   # Must serve token at /.well-known/sentinelx-verify.txt

# Scan profiles
scan_profiles:
  default:
    name: "Default Scan Profile"
    checks:
      - sql_injection
      - xss
      - broken_object_auth
      - missing_auth
      - sensitive_file_exposure
      - missing_rate_limit
      - security_headers
      - cors
      - verbose_errors
      - weak_upload
      - debug_exposure
    requests_per_second: 10
    burst: 10
    max_depth: 3
    max_pages: 100

# Fix policies
fix_policies:
  auto_apply: false
  require_approval: true
  max_fixes_per_run: 5

# Shield (reverse proxy) configuration
shield:
  mode: monitor  # monitor | recommend | enforce
  auto_shield: false
  fail_open: true
  listen:
    host: "127.0.0.1"
    port: 18090
  upstream: "http://127.0.0.1:18081"  # must be lab target
  size_caps:
    max_request_bytes: 1048576
    max_response_bytes: 1048576
  timeouts:
    connect_timeout_s: 5.0
    read_timeout_s: 15.0
  lab_mode: false
  kill_switch_file: null
  evidence_batch_interval_s: 5.0
  suspicious_rate_cap_per_min: 20
"""

AGENT_TEMPLATE = """# SentinelX Agent Guard Configuration
# Generated by: sentinelx init
# Edit this file to configure your agent guard policy.

version: "1.0"

# Policy mode: monitor | enforce
mode: "monitor"

# Allowed hosts for the agent to interact with
# In monitor mode, requests to disallowed hosts are logged but allowed.
# In enforce mode, requests to disallowed hosts are BLOCKED.
allowed_hosts: []

# Allowed tools the agent can call
# Each tool must be declared here to be usable
allowed_tools:
  - name: "fetch_page"
    description: "Fetch a web page"
    parameters:
      type: object
      properties:
        url:
          type: string
          format: uri
      required: ["url"]
  - name: "send_data"
    description: "Send data to a URL"
    parameters:
      type: object
      properties:
        url:
          type: string
          format: uri
        body:
          type: object
      required: ["url", "body"]

# High-impact actions that require human confirmation (CONFIRM)
# Only applies in enforce mode
high_impact_actions:
  - "send_data"
  - "execute_code"

# Secret patterns to redact from logs and model calls
secret_patterns:
  - "sk-[a-zA-Z0-9_-]{16,}"  # OpenAI-style keys
  - "gh[opusr]_[A-Za-z0-9]{20,}"  # GitHub tokens
  - "synth_tok_[0-9a-f]{8,}"  # Synthetic lab tokens

# Tool argument validation rules
tool_argument_rules:
  fetch_page:
    url:
      - pattern: "^https?://"
        message: "URL must use http or https"
  send_data:
    url:
      - pattern: "^https?://"
        message: "URL must use http or https"
    body:
      - type: "object"
        message: "body must be a JSON object"

# Blocked destinations (exact host matches)
blocked_destinations:
  - "evil.example"
  - "malicious.example"
"""
